// Long-running fishing script at Karamja Musa Point
// Goal: maximize peak XP rate via lobster cage / swordfish harpoon

const bot = globalThis.bot;
const sdk = globalThis.sdk;

const START = { x: 2924, z: 3178 };
const METHOD = process.env.FISH_METHOD || 'cage'; // cage | harpoon
const DURATION_MS = Number(process.env.DURATION_MS || 20 * 60 * 1000);

function keep(item: any) {
  if (!item) return false;
  return /harpoon|lobster pot|small fishing net|fly fishing rod|feather|coin/i.test(item.name);
}

async function dropFish() {
  const inv = sdk.getInventory().filter(Boolean);
  for (const item of inv) {
    if (!keep(item)) {
      await sdk.sendDropItem(item.slot);
    }
  }
}

